select
      a.id as resource,
      case
        when enable_client_certificate then 'ok'
        else 'alarm'
      end as status,
      case
        when enable_client_certificate then a.name || ' client certificate enabled.'
        else a.name || ' client certificate disabled.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_api_management a
      left join azure_subscription sub on a.subscription_id = sub.subscription_id;

select
      ag.id as resource,
      case
        when enable_http2 then 'ok'
        else 'alarm'
      end as status,
      case
        when enable_http2 then ag.name || ' HTTP2 enabled.'
        else ag.name || ' HTTP2 disabled.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "ag.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "ag.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_application_gateway as ag
      left join azure_subscription as sub on sub.subscription_id = ag.subscription_id;

select
      a.id as resource,
      case
        when type = 'microsoft.insights/components' and workspace_resource_id is not null then 'ok'
        else 'alarm'
      end as status,
      case
        when type = 'microsoft.insights/components' and workspace_resource_id is not null then a.name || ' linked to log analytics workspace.'
        else a.name || ' not linked to log analytics workspace.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "a.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_application_insight as a
      left join azure_subscription sub on sub.subscription_id = a.subscription_id;

select
      batch.id as resource,
      case
        when encryption ->> 'keySource' = 'Microsoft.KeyVault' then 'ok'
        else 'alarm'
      end as status,
      case
        when encryption ->> 'keySource' = 'Microsoft.KeyVault' then batch.name || ' encrypted with CMK.'
        else batch.name || ' not encrypted with CMK.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "batch.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "batch.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_batch_account as batch
      left join azure_subscription sub on batch.subscription_id = sub.subscription_id;

select
      b.id as resource,
      case
        when identity ->> 'type' = 'None' then 'alarm'
        else 'ok'
      end as status,
      case
        when identity ->> 'type' = 'None' then b.name || ' identity provider disabled.'
        else b.name || ' identity provider enabled.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "b.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "b.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_batch_account as b
      left join azure_subscription sub on b.subscription_id = sub.subscription_id;

select
      ag.id as resource,
      case
        when enable_http2 then 'ok'
        else 'alarm'
      end as status,
      case
        when enable_http2 then ag.name || ' HTTP2 enabled.'
        else ag.name || ' HTTP2 disabled.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "ag.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "ag.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_application_gateway as ag
      left join azure_subscription as sub on sub.subscription_id = ag.subscription_id;

select
      p.id as resource,
      case
        when (policy_settings -> 'requestBodyCheck')::bool then 'ok'
        else 'alarm'
      end as status,
      case
        when (policy_settings -> 'requestBodyCheck')::bool then p.name || ' request body inspection is enabled.'
        else p.name || ' request body inspection is disabled.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "p.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "p.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_web_application_firewall_policy as p
      left join azure_subscription sub on sub.subscription_id = p.subscription_id;

select
      c.id as resource,
      case
        when (x509_certificate_properties -> 'validity_months')::int <= 12 then 'ok'
        else 'alarm'
      end as status,
      c.title || ' validity period is ' || (x509_certificate_properties -> 'validity_months') || ' month(s).' as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "c.")}
      ${replace(local.common_dimensions_subscription_id_qualifier_sql, "__QUALIFIER__", "c.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_key_vault_certificate as c
      left join azure_subscription as sub on sub.subscription_id = c.subscription_id;

select
      ag.id as resource,
      case
        when ssl_policy is null or ((ssl_policy ->> 'minProtocolVersion') in ('TLSv1_2' , 'TLSv1_3')) then 'ok'
        else 'alarm'
      end as status,
      case
        when ssl_policy is null then ag.name || ' minimum TLS version set to TLSv1_2.'
        else ag.name || ' minimum TLS version set to ' || (ssl_policy ->> 'minProtocolVersion') || '.'
      end as reason
      ${replace(local.tag_dimensions_qualifier_sql, "__QUALIFIER__", "ag.")}
      ${replace(local.common_dimensions_qualifier_sql, "__QUALIFIER__", "ag.")}
      ${replace(local.common_dimensions_qualifier_subscription_sql, "__QUALIFIER__", "sub.")}
    from
      azure_application_gateway ag
      left join azure_subscription sub on sub.subscription_id = ag.subscription_id;

